          "how.back": "← Back",
          "how.documentTitle": "How it works - Rentulo",
          "how.findItem": "Find an item",
          "how.intro": "Rent items from people near you or list your own items for others in one place.",
          "how.listItem": "List an item",
          "how.note2Text": "The phone number and exact address are not public and are shown only to reservation participants.",
